fn hole(x: i32, y: i32) -> i32 {
    let mut a: i32 = x;
    let mut b: i32 = y;
    while (a > 0) || (b > 0) {
        if (a % 3 == 1) && (b % 3 == 1) { return 1; }
        a = a / 3;
        b = b / 3;
    }
    0
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let m: i32 = if w < h { w } else { h };
    let cs: i32 = m / 81;
    let ox: i32 = (w - cs * 81) / 2;
    let oy: i32 = (h - cs * 81) / 2;
    let p: i32 = t / 4 % 64;
    let tri: i32 = if p > 32 { 64 - p } else { p };
    let br: i32 = 150 + tri * 2;
    let c: i32 = br * 65536 + (br * 2 / 3) * 256 + 24;
    host::display::clear(0x140a04);
    let mut y: i32 = 0;
    while y < 81 {
        let mut x: i32 = 0;
        while x < 81 {
            if hole(x, y) == 0 {
                host::display::fill_rect(ox + x * cs, oy + y * cs, cs, cs, c);
            }
            x = x + 1;
        }
        y = y + 1;
    }
    host::display::present();
}
